{
  "name": "@tuzelko/opencode-delayed-message",
  "version": "0.3.6",
  "description": "Schedule a message that wakes an OpenCode session later, without showing it to the model first.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "delayed",
    "reminder",
    "scheduler",
    "timer",
    "desktop"
  ],
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "type": "module",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.ts",
    "./gui-experimental": "./gui-experimental.cjs"
  },
  "files": [
    "index.ts",
    "tui.ts",
    "rpc.ts",
    "gui-experimental.cjs",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "check": "tsc --noEmit",
    "build": "vite build",
    "prepare": "npm run build",
    "prepack": "npm run build"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/TuzelKO/opencode-delayed-message.git"
  },
  "homepage": "https://github.com/TuzelKO/opencode-delayed-message#readme",
  "bugs": {
    "url": "https://github.com/TuzelKO/opencode-delayed-message/issues"
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.5"
  },
  "devDependencies": {
    "@opentui/core": "^0.8.3",
    "@opentui/solid": "^0.8.3",
    "solid-js": "^1.9.18",
    "typescript": "^7.0.2",
    "vite": "^8.3.5",
    "vite-plugin-solid": "^2.11.15"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  }
}
